button.style:
font-family: 'Lexend', -apple-system, BlinkMacSystemFont, sans-serif;
font-weight: 300;
font-size: 16px;
letter-spacing: 0.3px;
background: #ffffff;
color: #000000;
border: none;
padding: 14px 32px;
border-radius: 60px;
cursor: pointer;
box-shadow: 0 6px 24px rgba(0,0,0,0.4);
transition: background 0.2s ease, transform 0.1s ease;
width: 100%;
height: 100%;
